<template><section class="patient-page"><header class="patient-page-header"><div><p class="eyebrow">BACK OFFICE</p><h1>Course Management</h1><p class="page-subtitle">จัดการข้อมูลแพ็กเกจ Course</p></div><button @click="reset">เพิ่ม Course</button></header><form class="profile-card" @submit.prevent="save"><h2>{{ editing?'แก้ไข Course':'สร้าง Course' }}</h2><div class="profile-grid"><label>Code<input v-model="form.code" maxlength="40" required /></label><label>ชื่อ Course<input v-model="form.name" maxlength="160" required /></label><label>ราคา<input v-model.number="form.price" type="number" min="0" step="0.01" required /></label><label>จำนวนครั้ง<input v-model.number="form.sessions" type="number" min="1" required /></label><label>Bonus Sessions<input v-model.number="form.bonusSessions" type="number" min="0" required /></label><label>Validity (days)<input v-model.number="form.validityDays" type="number" min="1" required /></label></div><p v-if="errorMessage" class="error">{{ errorMessage }}</p><button type="submit">บันทึก</button><button v-if="editing" type="button" class="secondary" @click="reset">ยกเลิก</button></form><div v-if="loading" class="state-card">กำลังโหลด...</div><div v-else-if="!courses.length" class="state-card">ยังไม่มีข้อมูล Course</div><div v-else class="patient-results"><article v-for="course in courses" :key="course.id" class="patient-result-card"><div><span class="patient-hn">{{ course.code }} · {{ course.sessions }} ครั้ง</span><h2>{{ course.name }}</h2><p>{{ course.price.toFixed(2) }} บาท · ใช้ได้ {{ course.validityDays }} วัน</p></div><div><span class="status-badge" :class="{ inactive: !course.active }">{{ course.active?'Active':'Inactive' }}</span><div class="actions"><button class="secondary" @click="edit(course)">แก้ไข</button><button v-if="course.active" class="secondary" @click="deactivate(course)">ปิดใช้งาน</button></div></div></article></div></section></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import{createCourse,deactivateCourse,listCourses,updateCourse,type Course,type CoursePayload}from'../api/courses';const courses=ref<Course[]>([]),loading=ref(true),editing=ref<number|null>(null),errorMessage=ref('');const empty=():CoursePayload=>({code:'',name:'',price:0,sessions:1,bonusSessions:0,validityDays:1});const form=ref(empty());async function load(){loading.value=true;try{courses.value=await listCourses()}catch(e){errorMessage.value=e instanceof Error?e.message:'โหลดข้อมูลไม่สำเร็จ'}finally{loading.value=false}}function reset(){editing.value=null;form.value=empty();errorMessage.value=''}function edit(c:Course){editing.value=c.id;form.value={code:c.code,name:c.name,price:c.price,sessions:c.sessions,bonusSessions:c.bonusSessions,validityDays:c.validityDays};errorMessage.value=''}async function save(){errorMessage.value='';try{if(editing.value)await updateCourse(editing.value,form.value);else await createCourse(form.value);reset();await load()}catch(e){errorMessage.value=e instanceof Error?e.message:'บันทึกไม่สำเร็จ'}}async function deactivate(c:Course){try{await deactivateCourse(c.id);await load()}catch(e){errorMessage.value=e instanceof Error?e.message:'ปิดใช้งานไม่สำเร็จ'}}onMounted(load)</script>
